    results = page['payment_requests'] if isinstance(page, dict) and 'payment_requests' in page else page
    if not results:
        break
    all_pending.extend(results)
    page_index += 1


def parse_iso(s):
    if s is None:
        return None
    try:
        return dt.fromisoformat(s.replace('Z','+00:00'))
    except Exception:
        return dt.fromisoformat(s)

month_pending = []
for pr in all_pending:
    created = parse_iso(pr.get('created_at'))
    if created is None:
        continue
    if month_start <= created < month_end:
        month_pending.append(pr)

target_ids = [pr['payment_request_id'] for pr in month_pending]

